<?php $isChat=($document??'base')==='recording';$name=$isChat?'شرایط نگهداری پیام‌های چت':'قوانین پایه';$prefix=$isChat?'/legal/recording':'/legal'; ?>
<h1><?= $name ?></h1><nav class="row section" aria-label="نوع سند"><a class="secondary" href="<?= $this->h($this->url('/legal')) ?>" <?= !$isChat?'aria-current="page"':'' ?>>قوانین حساب</a><a class="secondary" href="<?= $this->h($this->url('/legal?document=recording')) ?>" <?= $isChat?'aria-current="page"':'' ?>>شرایط نگهداری پیام‌های چت</a></nav>
<?php if($isChat): ?><p class="notice">برای فعال‌شدن چت، متن شرایط را ذخیره و سپس منتشر کنید. هر دو شرکت‌کننده باید شخصاً همین نسخه را در اتاق بپذیرند. انتشار نسخهٔ جدید پذیرش دوباره می‌خواهد. این سند به‌تنهایی ضبط صوت یا تصویر را فعال نمی‌کند.</p><?php endif; ?>
<section class="card section"><h2>ساخت نسخهٔ جدید</h2><?= $this->start($prefix.'/create') ?><?= $this->field('title','عنوان نسخه') ?><label for="body">متن مصوب <?= $name ?></label><textarea id="body" name="body" maxlength="60000" required rows="10"><?= $this->val('body') ?></textarea><button>ذخیرهٔ نسخه بدون انتشار</button></form></section>
<div class="records section"><?php foreach($rows as $row): ?><article class="card"><h2>نسخه <?= $this->h($row['version_no']) ?>: <?= $this->h($row['title']) ?></h2><div class="bodytext"><?= $this->h($row['body']) ?></div><p class="small ltr">SHA-256: <?= $this->h($row['content_sha256']) ?></p><?php if(($current['id']??null)===$row['id']): ?><span class="tag">نسخهٔ منتشرشدهٔ فعلی</span><?php else: ?><?= $this->start($prefix.'/publish') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><label class="row"><input type="checkbox" class="checkbox" name="confirmed" value="1" required>انتشار همین متن را تأیید می‌کنم.</label><button class="secondary">انتشار این نسخه</button></form><?php endif; ?></article><?php endforeach; ?></div>
